<div>
    <!-- Always remember that you are absolutely unique. Just like everyone else. - Margaret Mead -->
    {{--
    resources/views/components/map-loader.blade.php

    "Route scanner" loader: the real Philippines map (Luzon, Visayas, Mindanao) lights up
    from north to south as a laser scans down it. City pins pop in as the beam reaches them
    (Manila, Cebu, Davao), a glowing parcel travels the delivery route, and a live
    latitude / longitude readout and counter finish on "Nationwide".

    Use it INSTEAD of <x-page-loader />, right after <body> in your layout:
        <x-map-loader />

    Timing (see the two numbers in x-data):
        min    = first visit / refresh, at least this many ms
        navMin = every wire:navigate page change, at least this many ms

    Map data © OpenStreetMap contributors
--}}
@persist('page-loader')
<div
    x-data="{
        show: document.readyState !== 'complete',
        pct: 0,
        ready: false,
        start: Date.now(),
        min: 3200,      {{-- first visit: minimum ms --}}
        navMin: 1400,   {{-- page changes: minimum ms --}}
        dur: 3200,
        raf: null,
        safety: null,
        run() {
            cancelAnimationFrame(this.raf);
            const step = () => {
                const t = Math.min(1, (Date.now() - this.start) / this.dur);
                const eased = t < .5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
                const cap = this.ready ? 100 : 94;
                this.pct = Math.min(cap, Math.round(eased * 100));
                if (this.ready && this.pct >= 100) {
                    setTimeout(() => this.show = false, 650);
                    return;
                }
                this.raf = requestAnimationFrame(step);
            };
            step();
        },
        open() {
            this.dur = this.navMin;
            this.start = Date.now();
            this.pct = 0;
            this.ready = false;
            this.show = true;
            this.run();
            clearTimeout(this.safety);
            this.safety = setTimeout(() => this.ready = true, 6000); {{-- never get stuck --}}
        },
        get label() {
            return this.pct >= 100 ? 'Nationwide' : this.pct >= 74 ? 'Mindanao' : this.pct >= 52 ? 'Visayas' : this.pct >= 22 ? 'Luzon' : 'Locating';
        },
        get lat() { return (19.2 - this.pct * 0.138).toFixed(2); },
        get lon() { return (120.4 + this.pct * 0.059).toFixed(2); },
    }"
    x-init="
        if (show) {
            run();
            safety = setTimeout(() => ready = true, 6000);
        }
        window.addEventListener('load', () => ready = true);
        document.addEventListener('livewire:navigate', () => open());
        document.addEventListener('livewire:navigated', () => ready = true);
    "
    x-show="show"
    x-transition:leave="transition duration-700 ease-in"
    x-transition:leave-start="opacity-100 scale-100"
    x-transition:leave-end="opacity-0 scale-105"
    class="ml-loader fixed inset-0 z-[100] flex flex-col items-center justify-center overflow-hidden bg-blue-950"
    role="status"
    aria-live="polite"
    aria-label="Loading"
>
    <style>
        .ml-loader { --amber: 251 191 36; }

        .ml-grid { position:absolute; inset:0; opacity:.3;
            background-image: radial-gradient(rgba(255,255,255,.2) 1px, transparent 1px);
            background-size: 26px 26px;
            -webkit-mask-image: radial-gradient(circle at center, #000 0%, transparent 72%);
                    mask-image: radial-gradient(circle at center, #000 0%, transparent 72%); }
        .ml-lines { position:absolute; inset:0; pointer-events:none; opacity:.5;
            background: repeating-linear-gradient(0deg, rgba(255,255,255,.03) 0 1px, transparent 1px 4px); }
        .ml-glow { position:absolute; width:560px; height:560px; border-radius:9999px; pointer-events:none;
            background: radial-gradient(circle, rgb(var(--amber) / .13), transparent 65%); }

        .ml-map { overflow: visible; }
        .ml-ring  { transform-box: fill-box; transform-origin: center; }
        .ml-ring-a { animation: ml-rot 40s linear infinite; }
        .ml-ring-b { animation: ml-rot 26s linear infinite reverse; }
        .ml-ping { transform-box: fill-box; transform-origin: center; animation: ml-ping 1.6s ease-out infinite; }
        .ml-pin  { transition: opacity .5s ease; }
        .ml-lit  { filter: drop-shadow(0 0 7px rgb(var(--amber) / .55)); }

        .ml-corner { position:absolute; width:26px; height:26px; }
        .ml-c1 { top:22px; left:22px;  border-top:2px solid rgb(251 191 36 / .8); border-left:2px solid rgb(251 191 36 / .8); }
        .ml-c2 { top:22px; right:22px; border-top:2px solid rgb(251 191 36 / .8); border-right:2px solid rgb(251 191 36 / .8); }
        .ml-c3 { bottom:22px; left:22px;  border-bottom:2px solid rgb(251 191 36 / .8); border-left:2px solid rgb(251 191 36 / .8); }
        .ml-c4 { bottom:22px; right:22px; border-bottom:2px solid rgb(251 191 36 / .8); border-right:2px solid rgb(251 191 36 / .8); }

        .ml-bar { height:6px; width:min(340px, 74vw); background: rgba(255,255,255,.1); border-radius:9999px; overflow:hidden; }
        .ml-fill { height:100%; border-radius:9999px; transition: width .12s linear;
            background: linear-gradient(90deg, rgb(var(--amber) / .55), rgb(var(--amber)));
            box-shadow: 0 0 14px rgb(var(--amber) / .8); }

        @keyframes ml-rot  { to { transform: rotate(360deg); } }
        @keyframes ml-ping { from { transform: scale(.6); opacity:.9; } to { transform: scale(3.2); opacity:0; } }

        @media (prefers-reduced-motion: reduce) {
            .ml-ring-a, .ml-ring-b, .ml-ping { animation: none; }
        }
    </style>

    <div class="ml-grid" aria-hidden="true"></div>
    <div class="ml-lines" aria-hidden="true"></div>
    <div class="ml-glow" aria-hidden="true"></div>

    <span class="ml-corner ml-c1" aria-hidden="true"></span>
    <span class="ml-corner ml-c2" aria-hidden="true"></span>
    <span class="ml-corner ml-c3" aria-hidden="true"></span>
    <span class="ml-corner ml-c4" aria-hidden="true"></span>

    {{-- top HUD --}}
    <div class="absolute left-0 right-0 top-8 flex flex-col items-center gap-1 font-mono text-[10px] font-semibold uppercase tracking-[0.35em]" aria-hidden="true">
        <p class="font-montserrat text-lg font-extrabold tracking-[0.3em] text-white">i<span class="text-amber-400">CARGOXPRESS</span></p>
        <p class="text-white/40">Nationwide delivery <span class="text-amber-400">//</span> Philippines</p>
    </div>

