            <clipPath id="ml-clip">
                <rect x="200" y="0" width="500" :height="71 + 498 * pct / 100" />
            </clipPath>
            <clipPath id="ml-disc"><circle cx="440" cy="320" r="232" /></clipPath>
            <linearGradient id="ml-trail" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0" stop-color="#fbbf24" stop-opacity="0" />
                <stop offset="1" stop-color="#fbbf24" stop-opacity=".22" />
            </linearGradient>
        </defs>

        {{-- radar rings behind the map --}}
        <g class="ml-ring ml-ring-a" fill="none">
            <circle cx="440" cy="320" r="268" stroke="rgba(255,255,255,.14)" stroke-dasharray="2 7" />
        </g>
        <g class="ml-ring ml-ring-b" fill="none">
            <circle cx="440" cy="320" r="232" stroke="#fbbf24" stroke-opacity=".3" stroke-dasharray="14 10" />
        </g>
        <circle cx="440" cy="320" r="196" fill="none" stroke="rgba(255,255,255,.07)" />

        {{-- dim map (base) --}}
        <use href="#ml-islands" fill="rgba(255,255,255,.07)" stroke="rgba(255,255,255,.32)" stroke-width="0.8" stroke-linejoin="round" />

        {{-- amber map, revealed from north to south by the scan --}}
        <g clip-path="url(#ml-clip)" class="ml-lit">
            <use href="#ml-islands" fill="#fbbf24" fill-opacity=".9" stroke="#fde68a" stroke-width="0.8" stroke-linejoin="round" />
        </g>

        {{-- scan trail + beam (kept inside the radar disc) --}}
        <g clip-path="url(#ml-disc)">
            <rect x="200" :y="71 + 498 * pct / 100 - 70" width="500" height="70" fill="url(#ml-trail)" />
            <line x1="200" x2="680" :y1="71 + 498 * pct / 100" :y2="71 + 498 * pct / 100" stroke="#fff" stroke-width="1.5" style="filter: drop-shadow(0 0 5px #fbbf24)" />
        </g>

        {{-- delivery route Luzon > Visayas > Mindanao with a travelling parcel --}}
        <path id="ml-route" d="M417 286 C440 310 452 345 490 371 S542 432 547 466" fill="none" stroke="#fff" stroke-opacity=".5" stroke-width="1.2" stroke-dasharray="3 5" stroke-linecap="round" />
        <circle r="3.2" fill="#fff" style="filter: drop-shadow(0 0 5px #fbbf24)">
            <animateMotion dur="2.4s" repeatCount="indefinite" rotate="auto"><mpath href="#ml-route" /></animateMotion>
        </circle>

        {{-- city pins appear when the beam reaches them --}}
        <g class="ml-pin" :style="pct >= 43 ? 'opacity:1' : 'opacity:0'">
            <circle cx="417" cy="286" r="6" fill="none" stroke="#172554" stroke-width="1.5" class="ml-ping" />
            <circle cx="417" cy="286" r="5" fill="#172554" stroke="#fff" stroke-width="2" />
            <path d="M424 286 H440" stroke="#fff" stroke-opacity=".6" stroke-width=".8" />
            <text x="443" y="289" fill="#fff" font-size="9.5" font-weight="700" letter-spacing="1.2" class="font-montserrat">MANILA</text>
        </g>
        <g class="ml-pin" :style="pct >= 60 ? 'opacity:1' : 'opacity:0'">
            <circle cx="490" cy="371" r="6" fill="none" stroke="#172554" stroke-width="1.5" class="ml-ping" />
            <circle cx="490" cy="371" r="5" fill="#172554" stroke="#fff" stroke-width="2" />
            <path d="M497 371 H512" stroke="#fff" stroke-opacity=".6" stroke-width=".8" />
            <text x="515" y="374" fill="#fff" font-size="9.5" font-weight="700" letter-spacing="1.2" class="font-montserrat">CEBU</text>
        </g>
        <g class="ml-pin" :style="pct >= 79 ? 'opacity:1' : 'opacity:0'">
            <circle cx="547" cy="466" r="6" fill="none" stroke="#172554" stroke-width="1.5" class="ml-ping" />
            <circle cx="547" cy="466" r="5" fill="#172554" stroke="#fff" stroke-width="2" />
            <path d="M554 466 H566" stroke="#fff" stroke-opacity=".6" stroke-width=".8" />
            <text x="569" y="469" fill="#fff" font-size="9.5" font-weight="700" letter-spacing="1.2" class="font-montserrat">DAVAO</text>
        </g>
    </svg>

    {{-- readout --}}
    <div class="relative mt-5 flex w-[min(340px,74vw)] items-end justify-between font-mono">
        <div>
            <p class="text-[11px] font-semibold uppercase tracking-[0.3em] text-amber-300" x-text="label"></p>
            <p class="mt-1 text-[10px] tabular-nums tracking-widest text-white/45">
                LAT <span x-text="lat"></span>&deg;N &nbsp; LON <span x-text="lon"></span>&deg;E
            </p>
        </div>
        <span class="text-3xl font-bold leading-none tabular-nums text-white">
            <span x-text="String(pct).padStart(2, '0')"></span><span class="ml-0.5 text-base text-amber-400">%</span>
        </span>
    </div>

    <div class="relative mt-3">
        <div class="ml-bar"><div class="ml-fill" :style="`width:${pct}%`"></div></div>
    </div>
</div>
@endpersist

</div>
